{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Expose repeated preferences by scaling each input item vector by 1 + 0.1 * min(log1p(c), 2), where c counts matching nonpadding items strictly earlier in the supplied causal sequence. This adds no learned parameters and preserves the SASRec backbone, readout, loss and optimizer. The generated predictor imports this same SASRec class, so training and inference use identical features without checkpoint changes.",
      "edits": [
        {
          "find": "        seq_emb = self.item_emb(seq) * (self.hidden_units ** 0.5)\n\n        pos = torch.arange(M, device=seq.device).unsqueeze(0).expand(B, -1)",
          "replace": "        seq_emb = self.item_emb(seq) * (self.hidden_units ** 0.5)\n\n        # Count repeats strictly within each position's available causal prefix.\n        earlier = torch.tril(\n            torch.ones((M, M), dtype=torch.bool, device=seq.device), diagonal=-1\n        )\n        matches = seq.unsqueeze(2).eq(seq.unsqueeze(1))\n        matches = matches & earlier.unsqueeze(0)\n        matches = matches & seq.ne(0).unsqueeze(2) & seq.ne(0).unsqueeze(1)\n        repeat_count = matches.sum(dim=-1).to(dtype=seq_emb.dtype)\n        repeat_scale = 1.0 + 0.1 * torch.log1p(repeat_count).clamp(max=2.0)\n        seq_emb = seq_emb * repeat_scale.unsqueeze(-1)\n\n        pos = torch.arange(M, device=seq.device).unsqueeze(0).expand(B, -1)"
        },
        {
          "find": "NUM_EPOCHS   = int(os.environ.get(\"SASREC_EPOCHS\",    \"300\"))",
          "replace": "NUM_EPOCHS   = min(200, int(os.environ.get(\"SASREC_EPOCHS\", \"200\")))"
        },
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        }
      ]
    }
  ],
  "change_summary": "Add deterministic causal repeat-count input scaling, shared automatically by training and prediction. Preserve all four dataset models and enforce the required data directory and 200-epoch cap."
}
